contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_) public {
        require(amount_ > 0);
        require(loanToCollateral_ > 0);
        require(duration_ > 0);
        require(interest_ <= 1e18);

        uint256 interest1 = c.interestFor(amount_, interest_, duration_); if (__ESBMC_reverted()) return;
        uint256 interest2 = c.interestFor(amount_, interest_, duration_); if (__ESBMC_reverted()) return;

        assert(interest1 == interest2);
    }

    receive() external payable {}
}

