contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Cooler c;

    function setUp() public {
        c = new Cooler();
    }

    function _run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_) internal {
        vm.assume(amount_ > 0);
        vm.assume(loanToCollateral_ > 0);
        vm.assume(duration_ > 0);
        vm.assume(interest_ <= 1e18);
        uint256 interest1;
        try c.interestFor(amount_, interest_, duration_) returns (uint256 __r) { interest1 = __r; } catch { return; }
        uint256 interest2;
        try c.interestFor(amount_, interest_, duration_) returns (uint256 __r) { interest2 = __r; } catch { return; }
        assertTrue(interest1 == interest2);
    }

    function testFuzz_run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_) public {
        _run(amount_, interest_, loanToCollateral_, duration_);
    }

    receive() external payable {}
